-- Vida Sports Therapy - try with exact type name match
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'Vida Sports Therapy', 'vida-sports-therapy', 'Mobile sports massage therapy in Mallorca for cyclists, runners, and sports enthusiasts.', 'https://vidasportstherapy.com/', '+34 711 028 371', 'Mallorca', 'Spain', 'Mallorca', 'Palma', bt.id, sc.id, 1, 0
FROM businessTypes bt, sportCategories sc WHERE bt.name LIKE '%Massage%' AND sc.slug = 'cycling' LIMIT 1;

-- Running Mallorca
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'Running Mallorca', 'running-mallorca', 'Running trips and training camps for passionate runners across scenic coastal paths and mountain trails.', 'https://runningmallorca.com/', '+34662639020', 'Alaró', 'Spain', 'Mallorca', 'Alaró', (SELECT id FROM businessTypes WHERE name = 'Coach' LIMIT 1), (SELECT id FROM sportCategories WHERE slug = 'trail-running' LIMIT 1), 1, 0;

